import { cleanImageUrls } from "@/lib/utils";
import type { Category, Product } from "@/types";

// Image hosts used by placeholder and test data on the shared public API
const PLACEHOLDER_HOSTS =
  /(placehold|placeholder|placeimg|dummyimage|picsum|loremflickr|lorempixel|fakeimg)/i;

// Names generated by other students' automated tests, e.g. User_6b66821afc or title-<uuid>
const TEST_NAME = /^(user_|title-|desc-|test)|[_-][0-9a-f]{8,}$/i;

export function hasRealImage(images: unknown): boolean {
  return cleanImageUrls(images).some((url) => !PLACEHOLDER_HOSTS.test(url));
}

export function isStorefrontProduct(product: Product): boolean {
  return (
    typeof product.id === "number" &&
    typeof product.title === "string" &&
    product.title.trim().length > 0 &&
    typeof product.price === "number" &&
    !TEST_NAME.test(product.title.trim()) &&
    hasRealImage(product.images)
  );
}

export function getStorefrontProducts(products: Product[]): Product[] {
  return products.filter(isStorefrontProduct);
}

/** Only categories that contain at least one storefront-quality product. */
export function getStorefrontCategories(
  categories: Category[],
  storefrontProducts: Product[],
): Category[] {
  const used = new Set(storefrontProducts.map((p) => p.category?.id));
  return categories.filter(
    (c) => c && typeof c.slug === "string" && c.name && used.has(c.id),
  );
}
